struct S {union {struct {int a[2]; int b;}; int n;}; int z;};
static struct S v={.a[0]=1,2,3,4};
int main(void){return !(v.a[0]==1 && v.a[1]==2 && v.b==3 && v.z==4);}

struct A {int x;unsigned :3;}; struct S {struct A a;int y;};
static struct S v={.a.x=1,2};
int main(void){return !(v.a.x==1 && v.y==2);}

struct S {unsigned :3; unsigned a:4; unsigned :2; unsigned b:4; int z;}; struct T {struct S s; int z;};
static struct T v={.s.a=1,2,3,4};
int main(void){return !(v.s.a==1 && v.s.b==2 && v.s.z==3 && v.z==4);}
